"""Builds the vault's generated index: map, knowledge, tickets and lint."""

from __future__ import annotations

import re
from collections import defaultdict
from pathlib import Path

import core
import vault_lint
import vault_notes
from vault_notes import Note, as_list

INDEX_DIR = "index"
GENERATED = (
    "Generated by Erebor before and after every run. Don't edit "
    "it: change the notes and it follows."
)
MAP_INTRO = (
    "One line per note. An archived topic is off the dashboard, not out of "
    "date: what it decided still holds unless struck through."
)
KNOWLEDGE_INTRO = (
    "Every live statement in the areas and topics, one per line, tagged "
    "with its kind and its note. Superseded decisions are left out."
)
TICKETS_INTRO = (
    "Every ticket and pull request with a note, or that two or more notes "
    "mention, and where it comes up."
)
STATUS_ORDER = ("active", "paused", "proposed", "archived")
DROPPED = "dropped"
AGENT = "agent"
TICKET_SOURCES = ("linear", "github")
KINDS = {
    "Facts": "fact",
    "Decisions": "decision",
    "Constraints": "constraint",
    "Answered questions": "answered",
    "Open questions": "open question",
    "Gaps": "gap",
}
SUPERSEDED = "~~"
# What the map calls the other side of a topic-to-area tie.
PARTNER_LABEL = {"topics": "areas", "areas": "topics"}
SEE_ALSO_LIMIT = 5
MIN_MENTIONS = 2
TICKET = re.compile(r"(?<![\w-])[A-Z][A-Z0-9]*-\d+\b")
PULL_REQUEST = re.compile(r"\b([A-Za-z][\w.-]*)#(\d+)\b")


class Vault:
    """The notes, plus the lookups the index files share."""

    def __init__(self, notes: list[Note]):
        self.notes = notes
        self.named = defaultdict(list)
        for note in notes:
            self.named[note.name].append(note)
        self.areas = self._in("areas")
        self.people = self._in("people")
        self.sources = self._in("sources")
        topics = self._in("topics")
        self.dropped = [t for t in topics if t.meta.get("status") == DROPPED]
        self.topics = [t for t in topics if t.meta.get("status") != DROPPED]
        self.hubs = self.areas + self.topics
        self.evidence = {hub.name: self._evidence(hub) for hub in self.hubs}
        self.person_named = self._person_names()
        self.tickets = {
            source.name: source
            for source in self.sources
            if source.meta.get("source") in TICKET_SOURCES
        }
        self.mentions, self.labels = self._mentions()

    def _in(self, folder: str) -> list[Note]:
        return [note for note in self.notes if note.folder == folder]

    def _evidence(self, hub: Note) -> set:
        """Source notes tied to a hub by its links, theirs, or frontmatter."""
        return {
            source.name
            for source in self.sources
            if source.name in hub.links
            or hub.name in source.links
            or hub.name in as_list(source.meta.get(hub.folder))
        }

    def _person_names(self) -> dict:
        names = {}
        for person in self.people:
            known = [
                person.meta.get("name"),
                *as_list(person.meta.get("aliases")),
            ]
            names.update(
                {name.casefold(): person.name for name in known if name}
            )
        return names

    def _mentions(self) -> tuple[dict, dict]:
        """Which notes mention each ticket, and how the ticket is written."""
        mentions, labels = defaultdict(set), {}
        for note in self.notes:
            for key, label in self._references(note).items():
                mentions[key].add(note.name)
                labels.setdefault(key, label)
        return mentions, labels

    def _references(self, note: Note) -> dict:
        text = f"{note.meta.get('title', '')}\n{note.body}"
        found = {key: key for key in TICKET.findall(text)}
        for repo, number in PULL_REQUEST.findall(text):
            found[f"{repo}-{number}"] = f"{repo}#{number}"
        found.update(
            {name: name for name in note.links if name in self.tickets}
        )
        found.pop(note.name, None)
        return found

    def people_in(self, source: Note) -> set:
        names = as_list(source.meta.get("participants"))
        return {self.person_named.get(str(name).casefold()) for name in names}


def links(names) -> str:
    return ", ".join(f"[[{name}]]" for name in names)


def _count(number: int, noun: str) -> str:
    return f"{number} {noun}" if number == 1 else f"{number} {noun}s"


def _labelled(label: str, text: str) -> str:
    return f"{label}: {text}" if text else ""


def _joined(parts) -> str:
    return " · ".join(str(part) for part in parts if part)


def _section(title: str, lines: list) -> list:
    return [f"## {title}", "", *lines, ""] if lines else []


def _page(title: str, intro: str, lines: list) -> str:
    return "\n".join([f"# {title}", "", GENERATED, intro, "", *lines])


def _partners(vault: Vault, hub: Note) -> list:
    """A topic's areas, or the topics that name an area."""
    if hub.folder == "topics":
        return as_list(hub.meta.get("areas"))
    return [
        topic.name
        for topic in vault.topics
        if hub.name in as_list(topic.meta.get("areas"))
    ]


def _see_also(vault: Vault, hub: Note, shown: list) -> list:
    """Other hubs ranked by the sources they share and the links between."""
    mine, scores = vault.evidence[hub.name], {}
    for other in vault.hubs:
        if other.name == hub.name or other.name in shown:
            continue
        linked = (other.name in hub.links) + (hub.name in other.links)
        scores[other.name] = len(mine & vault.evidence[other.name]) + linked
    ranked = sorted(scores, key=lambda name: (-scores[name], name))
    return [name for name in ranked if scores[name]][:SEE_ALSO_LIMIT]


def _hub_line(vault: Vault, hub: Note) -> str:
    status = hub.meta.get("status")
    partners = _partners(vault, hub)
    used = sum(
        1
        for source in vault.sources
        if source.meta.get("source") == AGENT and hub.name in source.links
    )
    parts = [
        hub.meta.get("description"),
        _labelled("also", ", ".join(as_list(hub.meta.get("aliases")))),
        _labelled("updated", hub.meta.get("last_updated")),
        _count(len(vault.evidence[hub.name]), "source"),
        f"used {used}" if used else "",
        _labelled(PARTNER_LABEL[hub.folder], links(partners)),
        _labelled("see also", links(_see_also(vault, hub, partners))),
    ]
    head = f"[[{hub.name}]] — {status}" if status else f"[[{hub.name}]]"
    return f"- {head} — {_joined(parts)}"


def _person_line(vault: Vault, person: Note) -> str:
    seen = sum(1 for s in vault.sources if person.name in vault.people_in(s))
    parts = [
        person.meta.get("role"),
        _labelled("also", ", ".join(as_list(person.meta.get("aliases")))),
        f"in {_count(seen, 'source note')}",
    ]
    name = person.meta.get("name", person.name)
    return f"- [[{person.name}]] — {name} — {_joined(parts)}"


def _status_rank(topic: Note) -> tuple:
    status = topic.meta.get("status")
    rank = STATUS_ORDER.index(status) if status in STATUS_ORDER else 0
    return rank, topic.name


def render_map(vault: Vault) -> str:
    topics = sorted(vault.topics, key=_status_rank)
    dropped = [
        f"- {topic.name} — {topic.meta.get('description', '')}"
        for topic in vault.dropped
    ]
    lines = [
        *_section("Areas", [_hub_line(vault, a) for a in vault.areas]),
        *_section("Topics", [_hub_line(vault, t) for t in topics]),
        *_section("People", [_person_line(vault, p) for p in vault.people]),
        *_section("Dropped topics", dropped),
    ]
    return _page("Vault map", MAP_INTRO, lines)


def _statements(vault: Vault, heading: str) -> list:
    lines = []
    for hub in vault.hubs:
        status = hub.meta.get("status", "active")
        cite = f"[[{hub.name}]]" + (
            "" if status == "active" else f" ({status})"
        )
        live = [b for b in hub.sections.get(heading, []) if b[:2] != SUPERSEDED]
        lines += [f"- {KINDS[heading]} · {cite} · {bullet}" for bullet in live]
    return lines


def render_knowledge(vault: Vault) -> str:
    lines = []
    for heading in KINDS:
        lines += _section(heading, _statements(vault, heading))
    return _page("Live knowledge", KNOWLEDGE_INTRO, lines)


def _ticket_order(key: str) -> tuple:
    prefix, _, number = key.rpartition("-")
    return prefix, int(number) if number.isdigit() else 0, key


def _ticket_line(vault: Vault, key: str) -> str:
    note, label = vault.tickets.get(key), vault.labels.get(key, key)
    where = _labelled("in", links(sorted(vault.mentions.get(key, []))))
    if note is None:
        return f"- {label} — {_joined(['no note', where])}"
    source_id = note.meta.get("source_id")
    parts = [
        note.meta.get("title"),
        source_id if source_id != key else "",
        _labelled("topics", ", ".join(as_list(note.meta.get("topics")))),
        _labelled("areas", ", ".join(as_list(note.meta.get("areas")))),
        where,
    ]
    return f"- [[{key}]] — {_joined(parts)}"


def render_tickets(vault: Vault) -> str:
    keys = [
        key
        for key in {*vault.tickets, *vault.mentions}
        if key in vault.tickets or len(vault.mentions[key]) >= MIN_MENTIONS
    ]
    ordered = sorted(keys, key=_ticket_order)
    lines = [_ticket_line(vault, key) for key in ordered]
    return _page("Tickets and pull requests", TICKETS_INTRO, [*lines, ""])


def build(notes: list[Note]) -> dict:
    """Every index file's text, by file name."""
    vault = Vault(notes)
    return {
        "map.md": render_map(vault),
        "knowledge.md": render_knowledge(vault),
        "tickets.md": render_tickets(vault),
        "lint.md": _page("Lint", vault_lint.INTRO, vault_lint.render(vault)),
    }


def rebuild(vault: Path) -> int:
    """Rewrite the index folder; return how many entries lint lists."""
    files = build(vault_notes.load(vault))
    folder = vault / INDEX_DIR
    folder.mkdir(exist_ok=True)
    for name, text in files.items():
        (folder / name).write_text(core.neutralize_scripts(text))
    return files["lint.md"].count("\n- ")
